//! `docs-site/js/registry.js` — every component the example interpreter draws.
//!
//! # Why this is generated, and why it was not
//!
//! The file carried a `Generated by noctua-design — do not edit` header from
//! the day it was written, and nothing wrote it. Three checks read that line
//! and take it at its word: `xtask::gates::inspect` and
//! `xtask::references::inspect` both return early on a file carrying it, and
//! the drift loop in `xtask::check` only compares what [`crate::emit_all`]
//! produced. So the header bought three exemptions and delivered none of the
//! guarantee, and a component added to `spec/components/` was a name every tree
//! could carry and the browser could not draw.
//!
//! # The heavy split lives here, and so do the chunks
//!
//! Two chunks are fetched by name rather than shipped in the first one. That is
//! a decision about this site's payload rather than a fact about a contract, so
//! it is not in `spec/components/`. The chunk files are written from the same
//! table as the registry, so there is no second list to disagree with it.

use std::fmt::Write as _;

use noctua_design_spec::component::Component;

use crate::props::file_stem;
use crate::{COMPONENT_SPEC, CommentStyle, EmittedFile, header_from};

/// The React package's import specifier for one component's module.
const MODULE: &str = "@noctua-world/design-react/components";

/// One chunk fetched on demand: the file, why it is one, and what is in it.
struct Chunk {
    /// The file, under `docs-site/js/`.
    file: &'static str,
    /// The paragraph at the top of it, already wrapped.
    why: &'static str,
    /// The components it carries, by the name a tree uses.
    holds: &'static [&'static str],
}

/// Everything kept out of the first chunk.
const HEAVY: &[Chunk] = &[
    Chunk {
        file: "heavy-code.js",
        why: "It imports `@noctua-world/design-tokens/grammars.js`, which is 105 KB of\n\
              generated syntax grammars for thirty-four languages. Two pages on this site\n\
              show a code block, and the cost belongs to the person who asked for it.",
        holds: &["CodeBlock"],
    },
    Chunk {
        file: "heavy-lineage.js",
        why: "They import `@noctua-world/design-tokens/lineage.js`, the 65 KB layout\n\
              engine. One page shows them. See `heavy-code.js` for the argument; this is\n\
              the same one.",
        holds: &["Lineage", "LineageFigure"],
    },
];

/// The registry, and the chunks it defers to.
#[must_use]
pub fn emit(components: &[Component]) -> Vec<EmittedFile> {
    let mut files = vec![
        EmittedFile::new(
            "docs-site/src/generated/icon_props.rs",
            icon_props(components),
        ),
        EmittedFile::new("docs-site/js/registry.js", registry(components)),
    ];
    files.extend(
        HEAVY.iter().map(|chunk| {
            EmittedFile::new(format!("docs-site/js/{}", chunk.file), chunk_file(chunk))
        }),
    );
    files
}

/// Whether this component is fetched on demand rather than shipped eagerly.
fn deferred(name: &str) -> bool {
    HEAVY.iter().any(|chunk| chunk.holds.contains(&name))
}

/// The registry itself.
/// Which props carry an icon, by component.
///
/// The serialiser needs it and the browser does not: a tree written for React
/// carries the **drawing**, resolved here, rather than a name the browser would
/// have to import — and importing one module per icon name would be 1,777
/// dynamic imports in a bundle, which is the payload `NOCTUA.md §9.5` refuses.
pub(crate) fn icon_props(components: &[Component]) -> String {
    let mut out = header_from(CommentStyle::Line("//!"), COMPONENT_SPEC);
    out.push_str(
        "\n//! Which props take an icon, for the serialiser that has to resolve one.\n\n\
         /// `(component, props)`, in catalogue order.\n\
         pub(crate) const ICON_PROPS: &[(&str, &[&str])] = &[\n",
    );
    for component in components {
        let props: Vec<&str> = component
            .prop
            .keys()
            .filter(|name| crate::controls::dioxus_type(component, name).is_some())
            .map(String::as_str)
            .collect();
        if props.is_empty() {
            continue;
        }
        let listed = props
            .iter()
            .map(|name| format!("{name:?}"))
            .collect::<Vec<_>>()
            .join(", ");
        let _ = writeln!(out, "    ({:?}, &[{listed}]),", component.meta.name);
    }
    out.push_str("];\n");
    out
}

fn registry(components: &[Component]) -> String {
    let mut out = header_from(CommentStyle::Line("//"), COMPONENT_SPEC);
    out.push_str(
        "//\n\
         // Every component the example interpreter can draw, by the name a tree uses.\n\
         //\n\
         // Generated because a hand-written list of imports is a list that goes stale: a\n\
         // component added to `spec/components/` would be a name the trees carry and the\n\
         // browser cannot draw, and `example-react.js` throws on every page showing it.\n\
         //\n\
         // THE HEAVY ONES ARE NOT HERE. They are fetched by name, on the pages that name\n\
         // them, and `HEAVY` below is how.\n\n",
    );

    let eager: Vec<&Component> = components
        .iter()
        .filter(|component| !deferred(&component.meta.name))
        .collect();

    for component in &eager {
        let name = &component.meta.name;
        writeln!(
            out,
            "import {{ {name} }} from \"{MODULE}/{}.js\";",
            file_stem(name)
        )
        .expect("write");
    }

    out.push_str(
        "\n/** Every component that ships in the first chunk. */\nexport const COMPONENTS = {\n",
    );
    for component in &eager {
        writeln!(out, "  {},", component.meta.name).expect("write");
    }
    out.push_str(
        "};\n\n\
         /** The rest, behind a dynamic import, keyed by the name a tree uses. */\n\
         export const HEAVY = {\n",
    );
    for chunk in HEAVY {
        for name in chunk.holds {
            writeln!(out, "  {name}: () => import(\"./{}\"),", chunk.file).expect("write");
        }
    }
    out.push_str("};\n");
    out
}

/// One deferred chunk, re-exporting what it holds.
fn chunk_file(chunk: &Chunk) -> String {
    let mut out = header_from(CommentStyle::Line("//"), COMPONENT_SPEC);
    write!(out, "//\n// {}\n\n", chunk.why.replace('\n', "\n// ")).expect("write");
    for name in chunk.holds {
        writeln!(
            out,
            "export {{ {name} }} from \"{MODULE}/{}.js\";",
            file_stem(name)
        )
        .expect("write");
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contracts() -> Vec<Component> {
        let root = std::path::PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../.."));
        noctua_design_spec::component::load_all(root.join("spec/components"))
            .expect("the contracts parse")
    }

    /// A name in the heavy table that is not a component is a component in
    /// neither export, so the one page that shows it draws an empty stage and
    /// nothing reports it.
    #[test]
    fn every_heavy_name_is_a_component() {
        let components = contracts();
        for chunk in HEAVY {
            for name in chunk.holds {
                assert!(
                    components.iter().any(|it| it.meta.name == *name),
                    "`{name}` is in the {} chunk and is not a component",
                    chunk.file
                );
            }
        }
    }

    /// And every component is reachable from exactly one of the two exports.
    ///
    /// This is the guarantee the file's header claimed for a year and did not
    /// have. The floor is part of the assertion: a reader that found no
    /// contracts would otherwise pass by having nothing to check.
    #[test]
    fn every_component_is_reachable_from_the_registry() {
        let components = contracts();
        let text = registry(&components);
        for component in &components {
            let name = &component.meta.name;
            let eager = text.contains(&format!("\n  {name},\n"));
            let lazy = text.contains(&format!("\n  {name}: () => import("));
            assert!(eager || lazy, "{name} is in neither COMPONENTS nor HEAVY");
            assert!(!(eager && lazy), "{name} is in both COMPONENTS and HEAVY");
        }
        assert!(
            components.len() > 80,
            "only {} contracts were read, so this proves nothing",
            components.len()
        );
    }

    /// The chunk files re-export what the registry says they hold.
    #[test]
    fn each_chunk_exports_what_the_table_gives_it() {
        for chunk in HEAVY {
            let text = chunk_file(chunk);
            for name in chunk.holds {
                assert!(
                    text.contains(&format!("export {{ {name} }} from")),
                    "{} does not export {name}",
                    chunk.file
                );
            }
        }
    }
}
